// spec: .qa/e2e/specs/hunter-nda.md 4.1 · case: .qa/tests/hunter-nda/HN-4-1.md · tickets #0224f4 #1d9069
// OPT-IN (QA_AUTO_NDA=1), two roles (asUser). Written by autotest-writer 2026-11-08, NOT run.
// Selectors from QA screenshots 08.11 (0224f4-r2-*) — heal SELECTORS only, never the expected texts.
// Changes data: creates a pending auto NDA hunter→owner (repeatable while pending).
// QA_AUTO_NDA_APPROVE=1 → the owner approves: the pair is CONSUMED for 3 months. Never sends messages.
import { test, expect } from '../../fixtures';
import { composer, waitingBar, requestBar, readNdaView, expectDetails, expectComposerBlocked, todayIL, plus3Months } from './_auto';

const CFG = {
  enabled: process.env.QA_AUTO_NDA === '1',
  approve: process.env.QA_AUTO_NDA_APPROVE === '1',
  hunter: process.env.QA_AUTO_NDA_HUNTER || 'hunter_free',
  hunterName: process.env.QA_AUTO_NDA_HUNTER_NAME || 'הד האנטר דמו 2',
  owner: process.env.QA_AUTO_NDA_OWNER || 'company',
  ownerName: process.env.QA_AUTO_NDA_OWNER_NAME || 'סופר פארם',
  job: process.env.QA_AUTO_NDA_JOB || '/collaborations/fedc4b3d-3de6-414e-9821-af96a34469ae',
  jobTitle: process.env.QA_AUTO_NDA_JOB_TITLE || 'QA 0711 משרה חברה',
};

const SKIP_MSG =
  'OPT-IN: needs a hunter WITHOUT an NDA in force with the job owner (pairs are consumed). ' +
  'Run alone: QA_AUTO_NDA=1 [QA_AUTO_NDA_HUNTER/_HUNTER_NAME, _OWNER/_OWNER_NAME, _JOB/_JOB_TITLE, QA_AUTO_NDA_APPROVE=1] ' +
  'npx playwright test tests/hunter-nda/auto-nda-job-owner --project=tests --workers=1 — see specs/hunter-nda.md §4';

test.describe('Auto-signed standard NDA — first contact from a job page (#0224f4 #1d9069)', () => {
  test.skip(!CFG.enabled, SKIP_MSG);

  test('hunter → job «שליחת הודעה»: chat at once, waiting bar, filled NDA; owner «אישור ה-NDA»/«סירוב»; approve → +3 months @desktop @data #0224f4 #1d9069', async ({ asUser }) => {
    test.setTimeout(240_000);
    const hunter = await asUser(CFG.hunter);
    const owner = await asUser(CFG.owner);

    // 1. Hunter: job page → «מנהל/ת המשרה» → «שליחת הודעה» → chat opens directly (#1d9069 AC1–2)
    await hunter.goto(CFG.job);
    await expect(hunter.getByText(CFG.jobTitle).first()).toBeVisible({ timeout: 30_000 });
    await expect(hunter.getByText('מנהל/ת המשרה')).toBeVisible();
    await hunter.getByRole('button', { name: 'שליחת הודעה' }).first().click();
    await hunter.waitForURL(/\/messages\?c=/, { timeout: 30_000 });
    await expect(composer(hunter)).toBeVisible({ timeout: 30_000 });
    const chatId = new URL(hunter.url()).searchParams.get('c');
    expect(chatId, 'conversation id in URL').toBeTruthy();

    const hasBar = await waitingBar(hunter, CFG.ownerName).waitFor({ timeout: 15_000 }).then(() => true).catch(() => false);
    if (!hasBar && (await composer(hunter).isEnabled())) {
      test.skip(true, `NDA ${CFG.hunterName} ↔ ${CFG.ownerName} is already in force — need another pair (see specs/hunter-nda.md §4)`);
    }
    await expect(hunter.getByText('אפשר לכתוב אחרי האישור')).toBeVisible();
    await expectComposerBlocked(hunter, 'hunter waiting');

    // 2. Hunter: NDA filled before approval (#0224f4 AC2–3, rejection 07.11 п.2)
    const hText = await readNdaView(hunter);
    expectDetails(hText, {
      'שמכם:': CFG.hunterName,
      'הצד השני:': CFG.ownerName,
      'בנושא:': CFG.jobTitle,
      'חברה / מפרסם/ת המשרה:': CFG.ownerName,
      'תאריך:': /\d{2}\.\d{2}\.\d{4}/,
      'תוקף:': '3 חודשים מיום האישור של הצד השני',
    });
    expect(hText).toContain('נחתם אוטומטית בשמכם');
    expect(hText).toContain(`ממתין לאישור של ${CFG.ownerName}`);

    // 3. Owner: request bar with approve / refuse / view, composer blocked (#0224f4 AC3, AC5)
    await owner.goto(`/messages?c=${chatId}`);
    await expect(requestBar(owner, CFG.hunterName)).toBeVisible({ timeout: 30_000 });
    await expect(owner.getByText('וה-NDA הסטנדרטי ביניכם כבר חתום מצדם')).toBeVisible();
    await expect(owner.getByText('בתוקף ל-3 חודשים')).toBeVisible();
    await expect(owner.getByRole('button', { name: 'אישור ה-NDA' })).toBeVisible();
    await expect(owner.getByRole('button', { name: 'סירוב', exact: true })).toBeVisible();
    await expectComposerBlocked(owner, 'owner before approval');
    const oText = await readNdaView(owner);
    expectDetails(oText, {
      'שמכם:': CFG.ownerName,
      'הצד השני:': CFG.hunterName,
      'בנושא:': CFG.jobTitle,
      'חברה / מפרסם/ת המשרה:': CFG.ownerName,
    });

    if (!CFG.approve) return; // pair stays pending → the test is repeatable

    // 4. Owner approves → both can write; «הסכמים» start = today, end = today + 3 months (#0224f4 AC6)
    await owner.getByRole('button', { name: 'אישור ה-NDA' }).click();
    await expect(requestBar(owner, CFG.hunterName)).toBeHidden({ timeout: 30_000 });
    await expect(composer(owner)).toBeEnabled({ timeout: 30_000 });

    await hunter.reload();
    await expect(composer(hunter)).toBeEnabled({ timeout: 30_000 });
    await expect(waitingBar(hunter, CFG.ownerName)).toHaveCount(0);

    const today = todayIL();
    await hunter.goto('/profile?tab=agreements');
    await expect(hunter.getByText('תאריך חתימה')).toBeVisible({ timeout: 30_000 });
    const row = hunter.getByRole('row').filter({ hasText: CFG.ownerName }).filter({ hasText: today });
    await expect(row.first(), `«הסכמים»: row ${CFG.ownerName} signed ${today}`).toBeVisible({ timeout: 30_000 });
    await expect(row.first()).toContainText(plus3Months(today));
  });
});
